		conflictColumns := assetDocumentLinkConflictColumns[target]
		updateColumns := excludeColumns(columns, append(conflictColumns, "asset_id", "document_id"))

		query, queryArgs := sql.BuildInsert(c.dialect, c.table, sql.InsertOptions{
			Columns:             columns,
			Values:              args,
			UpsertConflictKeys:  conflictColumns,
			UpsertUpdateColumns: updateColumns,
		})
		_, err := conn.Exec(ctx, query, queryArgs...)
		if err != nil {
			return nil, fmt.Errorf("upsert asset_document_link: %w", err)
		}

